/** com.secta.hcbatch.job.hcon.mapper.HcTaskMapper.updateVchrInfo */
UPDATE /*+ INDEX(A T_HAPPYCON_COUPON_IDX2) */
T_HAPPYCON_COUPON A
SET A.UPD_ID = 'batch'
, A.UPD_DATE = (CASE WHEN ('' || #{cpnState}) IS NOT NULL OR ('' || #{avlEndDt}) IS NOT NULL OR ('' ||
#{remAmt}) IS NOT NULL THEN SYSDATE ELSE A.UPD_DATE END)

    , A.CPN_STATE = #{cpnState}


    , A.AVL_END_DT = #{avlEndDt}


    , A.REM_AMT = TO_NUMBER(#{remAmt})

, A.USE_TYPE = #{useType}
, A.TRX_AMT = #{trxAmt}
, A.USE_DTM = #{useDtm}
, A.BRAND_CODE = #{brndCd}
, A.STORE_CODE = #{stoCd}
, A.STORE_NAME = #{stoNm}
WHERE A.CPN_NO = #{vchrNo}
